"""Original aesthetics lesson with three audited ZCRE/Higgsfield image records."""
from hashlib import sha256
from html import escape
import json,re

PATH='/tutorials/cinematic-aesthetics/'
ART='/assets/tutorials/aesthetics/aesthetics-base.webp'
SHARE_ART='/assets/tutorials/aesthetics/aesthetics-share.jpg'
TITLE_KO='AI 이미지의 미감 만들기 — 여백·색·질감'
TITLE_EN='Cinematic AI images — space, color and texture'
DATE='2026-10-18'

def teaser(t):
 return '<a class="tutorial-preview" href="'+PATH+'"><img src="'+ART+'" width="1440" height="807" loading="lazy" alt="'+t('Midjourney v8.2 · 어두운 식물 기록보관소의 인물과 녹색 유리, 미감 실습','Midjourney v8.2 · A figure and green glass in a dark botanical archive, an aesthetics exercise')+'"><div><p class="section-eyebrow">MIDJOURNEY × HIGGSFIELD / VISUAL TASTE</p><h3>'+t(TITLE_KO,TITLE_EN)+'</h3><p class="tutorial-card-date"><time datetime="'+DATE+'">2026.10.18</time> · '+t('SF 미스터리 · 여백 · 색 · 질감','Science-fiction mystery · Space · Color · Texture')+'</p><span>'+t('세 장으로 읽는 미감 · 강좌 열기','Read visual choices through three images · Open lesson')+' →</span></div></a>'

def build(out,origin,head,header,footer,t):
 title=t(TITLE_KO,TITLE_EN)
 desc=t('지크 미드저니로 기준 이미지를 만들고 힉스필드 GPT Image 2.5로 여백과 재질감을 비교합니다. 초보자를 위한 시네마틱 이미지 미감 실습과 실제 사용한 전체 프롬프트.','Create a reference with ZCRE Midjourney, then explore negative space and tactile detail with Higgsfield GPT Image 2.5. A beginner exercise with the complete prompts actually used.')
 records=json.loads((out/'assets/tutorials/aesthetics/generation-manifest.json').read_text(encoding='utf-8'))
 def figure(index,ko,en,eager=False):
  record=records[index];src='/assets/tutorials/aesthetics/'+record['file']
  alts=[('Midjourney v8.2 · 심해 식물 기록보관소, 인물 오른쪽 배치, 어두운 녹색과 황동','Midjourney v8.2 · Deep-sea botanical archive, figure on the right, dark green and brass'),('GPT Image 2.5 · 넓은 여백, 전신 구도, 전경 식물과 깊은 복도','GPT Image 2.5 · Negative space, full figure, foreground plants and a deep corridor'),('GPT Image 2.5 · 허리 위 구도, 얼굴과 두 손, 코트 섬유와 낡은 황동','GPT Image 2.5 · Waist-up framing, face and hands, coat fibers and aged brass')]
  alt=t(*alts[index])
  return '<figure class="aesthetic-image"><a href="'+src+'" target="_blank" rel="noopener" aria-label="'+alt+'"><img src="'+src+'" width="'+str(record['width'])+'" height="'+str(record['height'])+'" alt="'+alt+'" '+('fetchpriority="high"' if eager else 'loading="lazy"')+' decoding="async"></a><figcaption>'+t(ko,en)+'</figcaption></figure>'
 def details(labelko,labelen,ko,en):
  return '<details class="tutorial-explain"><summary>'+t(labelko,labelen)+'</summary><p>'+t(ko,en)+'</p></details>'
 def prompt_card(index,ko,en):
  r=records[index]
  options=r['parameters'].copy();options.pop('prompt',None)
  if index:options['reference']='aesthetics-base.webp'
  dl='<dl class="aesthetic-record">'
  for a,b,value in [('사용 도구','Tool',r['tool']),('사용 모델','Model',r['model']),('요청 비율','Requested ratio',r['ratio']),('웹 이미지','Web image',str(r['width'])+' × '+str(r['height'])+' · '+str(round(r['bytes']/1024))+' KB')]:dl+='<div><dt>'+t(a,b)+'</dt><dd>'+escape(value)+'</dd></div>'
  dl+='</dl>'
  # These English strings are the exact submitted prompts in both language pages.
  return '<article class="aesthetic-prompt-card"><h3>'+t(ko,en)+'</h3>'+dl+'<p>'+t('실제 제출한 영어 프롬프트 원문입니다. 번역하거나 줄이지 않았습니다.','The exact English prompt submitted for this image, without translation or abridgment.')+'</p><details class="aesthetic-prompt"><summary>'+t('전체 프롬프트와 설정 열기','Open the complete prompt and settings')+'</summary><pre tabindex="0"><code>'+escape(r['prompt'])+'</code></pre><dl class="aesthetic-settings">'+''.join('<div><dt>'+escape(k)+'</dt><dd>'+escape(str(v))+'</dd></div>' for k,v in options.items())+'</dl><a class="text-button" href="/assets/tutorials/aesthetics/'+r['id']+'-prompt.txt" download>'+t('전체 프롬프트 TXT 다운로드','Download complete prompt TXT')+' ↓</a></details></article>'
 intro=t('먼저 보이는 곳, 남겨둔 공간, 손에 잡힐 듯한 재질. 세 가지 선택으로 어두운 장면의 분위기를 정리해 봅니다.','What catches your eye, the space you leave, and surfaces you can almost feel. Shape a dark scene through three visual choices.')
 body='<body class="watch-page">'+header()+'<main id="main" class="tutorial-main aesthetic-main"><a class="note-back" href="/tutorials/">← '+t('튜토리얼 목록','All tutorials')+'</a><header class="aesthetic-heading"><p class="section-eyebrow">VISUAL TASTE / ORIGINAL SCI-FI / STILL IMAGES</p><h1>'+title+'</h1><p class="tutorial-intro">'+intro+'</p><p class="tutorial-date"><time datetime="'+DATE+'">2026.10.18</time> · '+t('초보자 실습 · 이미지 3장 · 실제 생성 프롬프트','Beginner exercise · Three images · Actual generation prompts')+'</p><div class="aesthetic-tags"><span>ZCRE · Midjourney v8.2</span><span>Higgsfield · GPT Image 2.5</span><span>16:9</span></div></header>'
 body+=figure(0,'01 · 지크 Midjourney v8.2 기준 이미지. 유리의 식물 실루엣, 어두운 복도, 인물과 작은 황동 소품을 함께 봅니다.','01 · Reference generated with ZCRE Midjourney v8.2. Observe the plant silhouettes in glass, dark corridor, figure and small brass object.',True)
 body+='<nav class="tutorial-toc" aria-label="'+t('강좌 목차','Lesson contents')+'"><a href="#taste-first">'+t('시선의 순서','Visual hierarchy')+'</a><a href="#taste-space">'+t('여백 비교','Compare space')+'</a><a href="#taste-color">'+t('색과 질감','Color and texture')+'</a><a href="#taste-prompts">'+t('전체 프롬프트','Complete prompts')+'</a></nav>'
 body+='<section class="aesthetic-section" id="taste-first"><div class="aesthetic-section-heading"><p class="section-eyebrow">01 / DECIDE WHERE TO LOOK</p><h2>'+t('처음 1초에, 무엇이 보이나요?','What do you notice in the first second?')+'</h2></div><div class="aesthetic-reading"><p>'+t('위 이미지를 작게 보세요. 밝은 유리, 인물의 얼굴과 손, 작은 황동 상자 중 어디에 먼저 시선이 가는지 확인합니다. 이번 프롬프트는 얼굴과 손 → 상자 → 복도를 원했지만, 실제 결과에서는 왼쪽 유리도 눈을 강하게 끕니다. 의도와 결과를 따로 보는 것이 첫 단계입니다.','Look at the image as a small thumbnail. What catches your eye first: the bright glass, the face and hands, or the brass case? The prompt asked for face and hands → case → corridor, but the bright glass also competes strongly in the result. Start by separating intention from what the image actually does.')+'</p>'
 body+=details('직접 판단하는 방법','How to judge it yourself','완성 이미지를 휴대폰 화면만 하게 줄여 1초 동안 보고 시선을 뗍니다. 기억나는 것이 주인공인지, 유리의 밝은 띠인지 한 줄로 적으세요. 주인공을 먼저 보게 하고 싶다면 얼굴 주변의 작은 밝기 차이, 배경의 흰 반사, 소품의 크기를 한 번에 하나씩 조절하도록 요청합니다. 화면 전체를 밝게 올리면 원래의 어두운 분위기도 달라질 수 있습니다.','Shrink the result to roughly phone-screen size, look for a second, then look away. Write whether you remember the person or the bright strip of glass. If the person should read first, change one thing at a time: local contrast around the face, bright background reflections, or the size of the prop. Raising the exposure everywhere can change the dark mood too.')
 body+='</div></section>'
 body+='<section class="aesthetic-section" id="taste-space"><div class="aesthetic-section-heading"><p class="section-eyebrow">02 / SPACE CHANGES THE FEELING</p><h2>'+t('같은 소재, 다르게 느껴지는 거리.','The same subject, a different sense of distance.')+'</h2><p>'+t('기준 이미지 한 장을 두 작업에 똑같이 첨부했습니다. 넓은 구도는 공간의 깊이, 가까운 구도는 손과 표면의 정보를 더 보여줍니다.','The same reference image was attached to both jobs. The wide composition shows spatial depth; the closer composition reveals more of the hands and surfaces.')+'</p></div><div class="aesthetic-comparison"><article>'+figure(1,'02 · Higgsfield GPT Image 2.5. 전신과 바닥, 왼쪽 복도의 여백, 전경 식물 실루엣.','02 · Higgsfield GPT Image 2.5. Full figure, floor, space down the corridor and foreground plant silhouettes.')+'<h3>'+t('넓게: 인물이 머무는 공간.','Wide: the space around the person.')+'</h3><p>'+t('인물은 오른쪽에 있고 왼쪽에는 깊은 복도가 남습니다. 전경의 흐린 식물이 가까운 층을 만듭니다. 여백은 비어 있는 검정 면이 아니라, 관객이 공간을 읽을 수 있는 영역입니다.','The figure stays on the right, leaving a deep corridor on the left. Soft foreground plants create a nearer layer. Negative space is an area where the viewer can read the environment, rather than an empty black rectangle.')+'</p></article><article>'+figure(2,'03 · Higgsfield GPT Image 2.5. 얼굴·두 손·황동 상자를 포함한 가까운 구도.','03 · Higgsfield GPT Image 2.5. A closer composition including the face, both hands and brass case.')+'<h3>'+t('가까이: 인물이 만지는 물건.','Closer: the object in her hands.')+'</h3><p>'+t('코트의 섬유와 손, 낡은 상자가 커집니다. 공간 정보가 줄어든 만큼 인물과 물건의 관계가 더 또렷합니다. 이번 결과의 상자는 기준보다 길어졌습니다. 얼굴뿐 아니라 중요한 소품의 형태도 비교해야 합니다.','Coat fibers, hands and worn metal become larger. With less environmental information, the relationship between person and object reads more clearly. The case became longer than in the reference: compare important prop shapes as well as the face.')+'</p></article></div>'
 body+=details('참조 이미지를 넣고 따라 하기','Try it with a reference image','먼저 기준 이미지 파일을 저장합니다. 힉스필드에서 GPT Image 2.5를 고르고 실제 참고 이미지 입력칸에 그 파일을 첨부하세요. 이번 작업은 flare, medium, 1k, 16:9를 요청했습니다. 아래 원문은 하나의 첨부 이미지를 기준으로 작성했으며 파일 이름만 프롬프트에 적는 것으로 첨부가 완료되지는 않습니다. 얼굴·머리·의상·소품·장소는 유지할 대상으로, 구도의 넓이는 바꿀 대상으로 구분해 적습니다. 두 결과 모두 같은 기준 이미지를 첨부했고, 넓은 결과를 다시 가까운 결과의 참조로 쓰지는 않았습니다.','Save the reference image first. In Higgsfield, select GPT Image 2.5 and attach the file in the actual reference-image input. These jobs requested flare, medium, 1k and 16:9. The prompts assume one attached image; typing a filename does not attach it. Distinguish what should stay—face, hair, clothes, prop and location—from what should change—the framing. Both results used the same original reference; the wide result was not used as the reference for the closer one.')
 body+='<p class="tutorial-notice">'+t('두 이미지는 AI가 다시 해석한 예시입니다. 구도 외에도 얼굴·소품·빛이 조금 달라졌으므로, 구도만 바꾼 통제 실험이나 모델 우열 비교로 보지 않습니다.','These are AI reinterpretations. Face, prop and light changed somewhat alongside the framing, so this is neither a controlled framing-only experiment nor a ranking of the models.')+'</p></section>'
 body+='<section class="aesthetic-section" id="taste-color"><div class="aesthetic-section-heading"><p class="section-eyebrow">03 / A SMALL PALETTE, READABLE SURFACES</p><h2>'+t('색의 역할을 나누고, 재질을 읽습니다.','Give colors a role. Keep surfaces readable.')+'</h2></div><div class="aesthetic-palette" aria-label="'+t('실습 색상 역할','Color roles in this exercise')+'">'+''.join('<div class="palette-'+key+'"><span aria-hidden="true"></span><strong>'+t(ko,en)+'</strong><p>'+t(a,b)+'</p></div>' for key,ko,en,a,b in [('charcoal','차콜','Charcoal','코트와 어둠의 큰 면','Large areas of coat and shadow'),('green','탁한 녹색','Muted green','유리·벽·공간의 공통색','A shared hue for glass, walls and space'),('brass','낡은 황동','Aged brass','손에 든 작은 물건의 강조색','A small accent on the object in her hands')])+'</div><p>'+t('아래 색 조각은 색의 역할을 설명하는 예시이며, 이미지에서 측정한 정확한 색상표가 아닙니다. 녹색이 모든 피부와 물건을 덮는다면 인물의 피부는 자연스럽게, 황동은 빛나는 금색이 아닌 낡은 금속으로 분리해 요청해 보세요.','The swatches illustrate color roles; they are not exact colors measured from the image. If green overwhelms every surface, request more natural skin and aged brass rather than bright, glowing gold.')+'</p>'
 body+=details('어두운 이미지에서 확인할 네 가지','Four checks for a dark image','① 얼굴: 눈·코·입의 위치를 읽을 수 있는지 봅니다. ② 코트: 검은 덩어리만 남았는지, 소매와 앞판이 구분되는지 봅니다. ③ 금속: 주변보다 과하게 밝거나 플라스틱처럼 매끈한지 봅니다. ④ 배경: 모든 선이 똑같이 선명해서 인물을 방해하는지 봅니다. 문제가 있는 항목 하나를 정한 뒤 수정 문장을 붙이세요. 예를 들어 코트가 묻히면 “소매와 앞판의 미세한 명암 차이, 무광 섬유 결은 남기고 전체 밝기는 유지”처럼 씁니다.','① Face: can you locate the eyes, nose and mouth? ② Coat: can you distinguish sleeve from front panel, or is it one black mass? ③ Metal: is it too bright, or smooth like plastic? ④ Background: are all lines equally sharp and competing with the person? Choose one problem before adding a repair instruction. For a lost coat, try “retain subtle tonal separation between sleeve and front panel and matte cloth fibers, while keeping the overall dark exposure.”')
 body+='</section>'
 body+='<section class="aesthetic-section" id="taste-prompts"><div class="aesthetic-section-heading"><p class="section-eyebrow">04 / THE ACTUAL PROMPTS</p><h2>'+t('이미지와 함께 남기는 제작 기록.','Keep the generation record beside the image.')+'</h2><p>'+t('기준 이미지는 4개 후보 중 네 번째를 골랐습니다. 비교 이미지 2장을 더해 총 6장을 생성했고, 이 글에는 선택한 3장을 싣습니다. 후보를 고르는 과정도 미감 작업의 일부입니다.','The reference is the fourth of four Midjourney candidates. Two additional comparisons bring the total to six generated images; this article presents the three selected images. Choosing among candidates is part of the visual work.')+'</p></div>'
 for i,(ko,en) in enumerate([('01 · 미드저니 기준 이미지','01 · Midjourney reference'),('02 · 힉스필드, 넓은 여백','02 · Higgsfield, more negative space'),('03 · 힉스필드, 가까운 재질감','03 · Higgsfield, closer tactile detail')]):body+=prompt_card(i,ko,en)
 body+='<p class="tutorial-notice">'+t('16:9는 요청한 비율입니다. 실제 출력 치수와 웹 파일 용량은 각 카드에 기록했습니다. 게시용 파일만 WebP로 변환하고 연한 중앙 워터마크를 넣었으며, 색이나 조명을 보정해 비교 효과를 만들지는 않았습니다. 생성 비용과 제공 모델은 달라질 수 있으니 실행 전에 도구의 견적을 확인하세요.','16:9 is the requested ratio; each card records the actual web dimensions and file size. Publication copies were converted to WebP and given a faint central watermark. Color and lighting were not graded to manufacture the comparison. Model availability and generation prices can change; check the tool’s estimate before running a job.')+'</p></section>'
 body+='<section class="aesthetic-section"><p class="section-eyebrow">05 / YOUR FIRST PRACTICE</p><h2>'+t('첫 실습에서는 한 가지만 바꿔 보세요.','Change one thing in your first exercise.')+'</h2><ol class="aesthetic-practice"><li>'+t('자신의 소재로 기준 이미지 한 장을 고릅니다. 얼굴과 소품, 빛의 방향이 읽히는지 확인하세요.','Choose one reference for your own subject. Check that the face, prop and light direction are readable.')+'</li><li>'+t('“여백을 넓힌다” 또는 “손과 재질을 가까이 본다” 중 하나만 정합니다.','Choose either more surrounding space or a closer view of hands and materials.')+'</li><li>'+t('기준을 실제로 첨부하고 전체 프롬프트를 복사한 뒤, 인물·장소·소품을 자신의 설정으로 바꿉니다.','Attach your reference, copy the complete prompt, then replace the character, location and prop with your own details.')+'</li><li>'+t('두 결과를 같은 크기로 보고 의도한 변화 한 줄, 원치 않은 변화 한 줄을 적습니다.','Compare at the same display size. Write one intended change and one unwanted change.')+'</li></ol><p>'+t('추가 생성에 앞서 이미 나온 결과를 먼저 고르세요. 얼굴이나 상자가 달라졌다면 그 차이부터 수정하고, 배경·조명·포즈를 동시에 더하지 않습니다.','Review the results you already have before generating more. If the face or case changed, address that mismatch first instead of adding new background, lighting and pose changes together.')+'</p></section>'
 body+='<aside class="tutorial-ending"><h2>'+t('구도와 공간부터 더 익히고 싶다면.','Continue with framing and scene planning.')+'</h2><div class="tutorial-actions"><a class="button button-glass" href="/tutorials/camera-framing/">'+t('같은 장면, 어디까지 보여줄까?','Same scene. How much should you show?')+' →</a><a class="button button-glass" href="/tutorials/blender-previs/">'+t('생성하기 전에, 장면부터 설계하기','Plan the scene before generating it')+' →</a><a class="text-button" href="/questions/">'+t('미감 실습 질문 남기기','Ask about this exercise')+' →</a></div></aside></main>'+footer()+'</body></html>'
 schema={'@context':'https://schema.org','@type':'Article','headline':title,'description':desc,'url':origin+PATH,'image':origin+ART,'datePublished':DATE,'dateModified':DATE,'inLanguage':'ko','author':{'@type':'Organization','name':'DRA9ON CINEMA'},'keywords':['Midjourney','Higgsfield','GPT Image 2.5','cinematic composition','color','texture']}
 t(TITLE_KO+' | DRA9ON CINEMA',TITLE_EN+' | DRA9ON CINEMA')
 page=head(title+' | DRA9ON CINEMA',desc,PATH,schema).replace('property="og:type" content="video.episode"','property="og:type" content="article"')
 from image_dimensions import jpeg_size
 share_width,share_height=jpeg_size(out/SHARE_ART.lstrip('/'))
